<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {WorkflowCommandError} from './workflow-operation'
import type {ReadinessTask,WorkflowOperationProvider,WorkflowOperationRecord,WorkflowStage} from './workflow-operation'
const props=defineProps<{provider:WorkflowOperationProvider;records:WorkflowOperationRecord[];selectedId:string;selectedIds:string[];trashView:boolean;storage:Pick<Storage,'getItem'|'setItem'|'removeItem'>|null;busy:boolean}>()
const emit=defineEmits<{(event:'record',record:WorkflowOperationRecord):void;(event:'purged',id:string):void;(event:'view',trash:boolean):void;(event:'selected',ids:string[]):void;(event:'locked',value:boolean):void}>()
type Kind='stages'|'trash'|'restore'|'purge'
type Pending={id:string;kind:Kind;operationId:string;expectedRevision:number;stages?:WorkflowStage[]}
const key='companion.workflow-management.pending.v1',pending=ref<Pending|null>(null),corrupt=ref(false),working=ref(false),message=ref(''),purgeConfirm=ref(false)
const item=computed(()=>props.records.find(r=>r.id===props.selectedId))
const drafts=ref<WorkflowStage[]>([]),tasks=ref<ReadinessTask[]>([]),taskError=ref('')
const draftBase=ref<WorkflowStage[]>([]),draftRevision=ref(0),draftConflict=ref(false)
const draftCache=new Map<string,{revision:number;base:WorkflowStage[];stages:WorkflowStage[]}>()
const cloneStages=(stages:WorkflowStage[])=>JSON.parse(JSON.stringify(stages)) as WorkflowStage[]
const dirty=computed(()=>JSON.stringify(drafts.value)!==JSON.stringify(draftBase.value))
const unsafeStates=new Set(['planning','starting','queued','running','pause-requested','paused','resuming','unknown'])
const guarded=(r:WorkflowOperationRecord)=>unsafeStates.has(r.state)
function persist(value:Pending|null){if(!props.storage)throw Error('STORAGE_UNAVAILABLE');if(value){const text=JSON.stringify(value);props.storage.setItem(key,text);if(props.storage.getItem(key)!==text)throw Error('STORAGE_UNCONFIRMED')}else{props.storage.removeItem(key);if(props.storage.getItem(key)!==null)throw Error('STORAGE_UNCONFIRMED')}pending.value=value}
function restore(){try{if(!props.storage)throw Error();const text=props.storage.getItem(key);if(!text)return;const v=JSON.parse(text);if(!v||typeof v.id!=='string'||typeof v.operationId!=='string'||!['stages','trash','restore','purge'].includes(v.kind)||!Number.isSafeInteger(v.expectedRevision)||v.expectedRevision<0||(v.kind==='stages'&&!Array.isArray(v.stages)))throw Error();pending.value=v}catch{corrupt.value=true}}
restore()
watch([pending,corrupt,working],()=>emit('locked',!!pending.value||corrupt.value||working.value),{immediate:true})
watch(()=>[item.value?.id,item.value?.management?.revision] as const,(next,previous)=>{const [id,revision]=next,oldId=previous?.[0];if(oldId&&oldId!==id)draftCache.set(oldId,{revision:draftRevision.value,base:cloneStages(draftBase.value),stages:cloneStages(drafts.value)});if(!id){drafts.value=[];draftBase.value=[];draftRevision.value=0;draftConflict.value=false;return}const latest=cloneStages(item.value?.management?.stages??[]),currentRevision=revision??0;if(oldId!==id){const saved=draftCache.get(id);drafts.value=saved?cloneStages(saved.stages):cloneStages(latest);draftBase.value=saved?cloneStages(saved.base):cloneStages(latest);draftRevision.value=saved?.revision??currentRevision;tasks.value=[];taskError.value='';purgeConfirm.value=false}if(draftRevision.value!==currentRevision){if(dirty.value&&JSON.stringify(drafts.value)!==JSON.stringify(latest)){draftConflict.value=true;return}drafts.value=cloneStages(latest);draftBase.value=cloneStages(latest);draftRevision.value=currentRevision}draftConflict.value=false},{immediate:true,flush:'sync'})
function loadLatestStages(){const r=item.value;if(!r)return;drafts.value=cloneStages(r.management?.stages??[]);draftBase.value=cloneStages(drafts.value);draftRevision.value=r.management?.revision??0;draftConflict.value=false;draftCache.delete(r.id)}
function confirmed(r:WorkflowOperationRecord,p:Pending){if(r.id!==p.id||!r.management||r.management.revision<=p.expectedRevision)return false;if(p.kind==='trash')return !!r.management.trashedAt;if(p.kind==='restore')return r.management.trashedAt===null;if(p.kind==='stages')return JSON.stringify(r.management.stages)===JSON.stringify(p.stages);return false}
async function send(kind:Kind,r:WorkflowOperationRecord,stages?:WorkflowStage[]){
 if(working.value||pending.value||corrupt.value||props.busy)return false
 if(kind==='trash'&&(r.management?.trashedAt||guarded(r))||kind==='restore'&&!r.management?.trashedAt||kind==='purge'&&(!r.management?.trashedAt||guarded(r))||kind==='stages'&&!!r.management?.trashedAt)return false
 const op=crypto.randomUUID(),p:Pending={id:r.id,kind,operationId:op,expectedRevision:kind==='stages'?draftRevision.value:r.management?.revision??0,...(stages?{stages:cloneStages(stages)}:{})}
 try{persist(p)}catch{corrupt.value=true;message.value='无法保存请求，未提交。';return false}
 working.value=true;message.value=''
 try{
  if(kind==='purge'){if(!props.provider.purgeGoal)throw Error();const result=await props.provider.purgeGoal(r.id,{operationId:op,expectedRevision:p.expectedRevision});if(result.workflowId!==r.id||result.operationId!==op||result.purged!==true)throw Error();persist(null);emit('purged',r.id)}
  else {const fn=kind==='stages'?props.provider.updateStages:kind==='trash'?props.provider.trashGoal:props.provider.restoreGoal;if(!fn)throw Error();const input={operationId:op,expectedRevision:p.expectedRevision,...(kind==='stages'?{stages:p.stages!}:{})};const result=await fn(r.id,input as never);if(!confirmed(result,p))throw Error();persist(null);emit('record',result)}
  emit('selected',props.selectedIds.filter(id=>id!==r.id));message.value=kind==='purge'?'记录已永久删除；磁盘交付和底层日志保留。':'已保存。';return true
 }catch(e){if(e instanceof WorkflowCommandError&&e.outcome==='rejected'){try{persist(null)}catch{corrupt.value=true}message.value=e.code==='MANAGEMENT_EXECUTION_UNCONFIRMED'?'缺少可核验的执行结束记录，暂不可删除。':'请求被拒绝，请读取最新状态并核对删除条件。'}else message.value='结果待核对；已保留原请求，不会自动重发。';return false}finally{working.value=false}
}
async function reconcile(){const p=pending.value;if(!p||working.value)return;working.value=true;try{const result=await props.provider.getOperation(p.operationId,p.id);if(result.operationId!==p.operationId||result.workflowId!==p.id)throw Error();if(result.state==='rejected'&&result.outcome==='not-applied'&&result.code==='MANAGEMENT_NOT_APPLIED_RECORD_CHANGED'){persist(null);message.value='原操作未应用，请加载最新后重新保存；阶段草稿已保留。';return}if(result.state!=='settled')throw Error();if(p.kind==='purge'){if(!result.result||result.result.workflowId!==p.id||result.result.operationId!==p.operationId||!result.result.purged)throw Error();persist(null);emit('purged',p.id)}else{if(!result.record||result.record.id!==p.id||!result.record.management||result.record.management.revision<=p.expectedRevision)throw Error();const changed=!confirmed(result.record,p);persist(null);emit('record',result.record);message.value=changed?'原请求已完成，当前记录有更新。':'已核对原请求结果。'}if(p.kind==='purge')message.value='已核对原请求结果。'}catch{message.value='原请求仍未确认；不会自动重发。'}finally{working.value=false}}
async function continueOriginal(){const p=pending.value;if(!p||working.value)return;working.value=true;try{if(p.kind==='purge'){if(!props.provider.purgeGoal)throw Error();const result=await props.provider.purgeGoal(p.id,{operationId:p.operationId,expectedRevision:p.expectedRevision});if(result.workflowId!==p.id||result.operationId!==p.operationId||result.purged!==true)throw Error();persist(null);emit('purged',p.id)}else{const fn=p.kind==='stages'?props.provider.updateStages:p.kind==='trash'?props.provider.trashGoal:props.provider.restoreGoal;if(!fn)throw Error();const result=await fn(p.id,{operationId:p.operationId,expectedRevision:p.expectedRevision,...(p.kind==='stages'?{stages:p.stages!}:{})} as never);if(!confirmed(result,p))throw Error();persist(null);emit('record',result)}message.value='原请求已完成。'}catch(e){if(e instanceof WorkflowCommandError&&e.outcome==='rejected'&&e.code==='MANAGEMENT_NOT_APPLIED_RECORD_CHANGED'){try{persist(null);message.value='原操作未应用，请加载最新后重新保存；阶段草稿已保留。'}catch{corrupt.value=true;message.value='无法清除请求记录，保持锁定。'}}else message.value='原请求仍待核对；请求标识保持不变。'}finally{working.value=false}}
async function bulk(kind:'trash'|'restore'|'purge'){const rows=props.records.filter(r=>props.selectedIds.includes(r.id));for(const r of rows){if(!await send(kind,r))break}purgeConfirm.value=false}
async function loadTasks(){const r=item.value;if(!r?.plan||!props.provider.readReadiness)return;taskError.value='';try{const data=await props.provider.readReadiness(r.id);if(item.value?.id!==r.id||item.value.plan?.digest!==r.plan.digest||data.workflowId!==r.id||data.planDigest!==r.plan.digest)throw Error();tasks.value=data.tasks}catch{tasks.value=[];taskError.value='计划任务读取失败，请重新核对。'}}
function addStage(){if(drafts.value.length<50)drafts.value.push({id:crypto.randomUUID(),title:'',outcome:'',taskRefs:[]})}
function move(i:number,d:number){const j=i+d;if(j<0||j>=drafts.value.length)return;[drafts.value[i],drafts.value[j]]=[drafts.value[j]!,drafts.value[i]!]}
function assignTask(task:ReadinessTask,stageId:string){const digest=item.value?.plan?.digest;if(!digest)return;for(const stage of drafts.value)stage.taskRefs=stage.taskRefs.filter(r=>!(r.planDigest===digest&&r.taskId===task.id));const target=drafts.value.find(s=>s.id===stageId);if(target)target.taskRefs.push({planDigest:digest,taskId:task.id})}
function toggleTask(stage:WorkflowStage,task:ReadinessTask,checked:boolean){assignTask(task,checked?stage.id:'')}
function stageProgress(stage:WorkflowStage){const r=item.value,current=stage.taskRefs.filter(x=>x.planDigest===r?.plan?.digest);if(!r||!current.length)return '暂无当前计划任务';let completed=0,accepted=0;for(const ref of current){const run=[...r.runs].reverse().find(x=>x.planDigest===ref.planDigest&&x.selectedTaskId===ref.taskId);if(!run?.executionId)continue;const verified=run.state==='accepted'&&run.acceptance?.goalDigest===run.goalDigest&&run.acceptance?.planDigest===run.planDigest&&((run.acceptance.scope==='technical-sample'&&run.capability==='restricted-readonly-model-output')||(run.acceptance.scope==='task-directory'&&run.capability==='task-directory-workspace-write'&&run.taskWorkspace?.relativePath===`.companion/tasks/${r.id}`));if(run.state==='completed'||verified)completed++;if(verified)accepted++}return `执行完成 ${completed} / ${current.length} · 已验收 ${accepted} / ${current.length}`}
const unassignedTasks=computed(()=>tasks.value.filter(task=>!drafts.value.some(stage=>stage.taskRefs.some(ref=>ref.planDigest===item.value?.plan?.digest&&ref.taskId===task.id))))

const valid=computed(()=>drafts.value.every(s=>s.title.trim().length>0&&s.title.length<=200&&s.outcome.length<=2000&&!/[\x00-\x1f\x7f]/.test(s.title)&&!/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(s.outcome)))
</script>
<template>
 <section aria-label="记录管理" class="management">
  <div class="toolbar"><button type="button" @click="emit('view',!trashView);emit('selected',[])">{{ trashView?'返回目标':'回收站' }}</button><span v-if="pending" role="status">{{ pending.id }} 的请求待核对 <button type="button" :disabled="working" @click="reconcile">查询原请求</button><button type="button" :disabled="working" @click="continueOriginal">继续原管理请求</button></span><span v-if="corrupt" role="alert">请求记录不可用，管理操作已锁定。</span><span v-if="message" role="status">{{ message }}</span></div>
  <p>目标管理在本地记录；规划和执行会消耗模型 token。</p>
  <div v-if="trashView"><p>永久删除仅移除后台记录，源码、磁盘交付和底层日志保留。</p><button type="button" :disabled="!selectedIds.length||working||!!pending" @click="bulk('restore')">批量恢复</button><button type="button" :disabled="!selectedIds.length||working||!!pending" @click="purgeConfirm=true">永久删除</button><el-dialog v-model="purgeConfirm" title="永久删除记录" align-center><p>将永久删除 {{ selectedIds.length }} 条后台记录，源码、磁盘交付和底层日志保留。此操作不可撤销。</p><ul><li v-for="r in records.filter(x=>selectedIds.includes(x.id))" :key="r.id">{{ r.presentation?.title||r.id }} · {{ r.management?.stages.length??0 }} 个阶段及其关联</li></ul><template #footer><el-button @click="purgeConfirm=false">取消</el-button><el-button type="danger" :disabled="working||!!pending" @click="bulk('purge')">确认永久删除</el-button></template></el-dialog></div>
  <div v-else><button type="button" :disabled="!selectedIds.length||working||!!pending" @click="bulk('trash')">移入回收站</button></div>
  <section v-if="item&&!item.management?.trashedAt" aria-label="目标阶段"><h4>阶段</h4><p>阶段只管理计划，不会启动模型或更改审阅计划。</p><p v-if="dirty">有未保存的阶段草稿，切换目标后仍保留。</p><p v-if="draftConflict" role="alert">阶段已在其他位置更新；草稿保留。保存会按原版本核对，不会覆盖更新。<button type="button" @click="loadLatestStages">放弃草稿并加载最新阶段</button></p><p v-if="!drafts.length">尚无阶段。</p><article v-for="(stage,i) in drafts" :key="stage.id"><p>{{ stageProgress(stage) }}</p><label>阶段名称<input v-model="stage.title" maxlength="200"></label><label>阶段成果<textarea v-model="stage.outcome" maxlength="2000" /></label><button type="button" @click="move(i,-1)" :disabled="i===0">上移</button><button type="button" @click="move(i,1)" :disabled="i===drafts.length-1">下移</button><button type="button" @click="drafts.splice(i,1)">删除阶段</button><p v-for="ref in stage.taskRefs" :key="ref.planDigest+ref.taskId">{{ ref.taskId }} · {{ ref.planDigest===item.plan?.digest?'当前计划':'旧计划绑定，待确认' }} <button type="button" @click="stage.taskRefs=stage.taskRefs.filter(x=>x!==ref)">移除关联</button></p><label v-for="task in tasks" :key="task.id"><input type="checkbox" :checked="stage.taskRefs.some(x=>x.planDigest===item?.plan?.digest&&x.taskId===task.id)" @change="toggleTask(stage,task,($event.target as HTMLInputElement).checked)">{{ task.id }} · {{ task.text }}</label></article><p v-if="item.runs.some(run=>!run.selectedTaskId)">部分历史执行未提供任务关联，无法计入阶段进度。</p><div v-if="tasks.length"><h5>未分阶段</h5><p v-if="!unassignedTasks.length">当前计划任务均已分配。</p><label v-for="task in unassignedTasks" :key="task.id">{{ task.id }} · {{ task.text }} <select :value="''" @change="assignTask(task,($event.target as HTMLSelectElement).value)"><option value="">选择阶段</option><option v-for="stage in drafts" :key="stage.id" :value="stage.id">{{ stage.title||'未命名阶段' }}</option></select></label></div><button type="button" @click="addStage">新增阶段</button><button type="button" :disabled="!item.plan||working" @click="loadTasks">读取当前计划任务</button><p v-if="taskError" role="status">{{ taskError }}</p><button type="button" :disabled="!valid||working||!!pending||corrupt||!provider.updateStages" @click="send('stages',item,drafts)">保存阶段</button></section>
 </section>
</template>
<style scoped>
.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.management label{display:block;margin:8px 0}.management small{color:var(--el-text-color-secondary)}.management article{border:1px solid var(--el-border-color);padding:12px;margin:12px 0}.management input:not([type=checkbox]){margin-left:8px}
</style>
